// Native helper for requesting and checking location permissions on Capacitor Android
import { Capacitor } from '@capacitor/core';
import { Geolocation } from '@capacitor/geolocation';

export async function requestLocationPermission() {
  if (!Capacitor.isNativePlatform()) {
    console.warn('Location permission request skipped: not native platform.');
    return false;
  }

  try {
    const status = await Geolocation.checkPermissions();
    const isGranted = status.location === 'granted' || status.location === 'granted';
    if (isGranted) {
      return true;
    }

    const permission = await Geolocation.requestPermissions();
    return permission.location === 'granted';
  } catch (err) {
    console.error('Failed to request location permissions:', err);
    return false;
  }
}

export async function getCurrentPosition() {
  if (!Capacitor.isNativePlatform()) {
    console.warn('getCurrentPosition skipped: not native platform.');
    return null;
  }

  try {
    const position = await Geolocation.getCurrentPosition();
    return position;
  } catch (err) {
    console.warn('Failed to get current position:', err);
    return null;
  }
}

export async function disableLocationTracking() {
  if (!Capacitor.isNativePlatform()) {
    console.warn('Location tracking disable skipped: not native platform.');
    return;
  }

  try {
    // On Android, we can't actually revoke permissions programmatically,
    // but we mark the preference as disabled so the app won't request or use location.
    // The OS permission will remain granted, but the app respects the allow_location flag.
    console.log('Location tracking disabled in app (OS permission remains, but app won\'t use it)');
    return;
  } catch (err) {
    console.warn('Failed to disable location tracking:', err);
  }
}
